#!/usr/bin/env node
/**
 * Vendors RetroCSS's compiled bundle into assets/retrocss/.
 *
 * The theme ships the built CSS and JS rather than compiling from source,
 * because Hugo can only transpile Sass in its *extended* build. Vendoring keeps
 * the theme buildable by every Hugo, offline, with no npm step.
 *
 *   node scripts/vendor-retrocss.mjs                 # from ../RetroCSS
 *   node scripts/vendor-retrocss.mjs --from ../foo   # from another checkout
 *   node scripts/vendor-retrocss.mjs --npm           # from the published package
 */
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const THEME = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(THEME, 'assets', 'retrocss');
const FILES = ['retro.min.css', 'retro.min.js'];

const argv = process.argv.slice(2);
const useNpm = argv.includes('--npm');
const fromArg = argv[argv.indexOf('--from') + 1];
const from = argv.includes('--from') ? path.resolve(fromArg) : path.resolve(THEME, '..', 'RetroCSS');

function die(msg) {
  console.error(`vendor-retrocss: ${msg}`);
  process.exit(1);
}

/** Unpacks the published tarball into a temp dir and returns its package root. */
function fromNpm() {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'retrocss-'));
  execFileSync('npm', ['pack', '@phantompixeldev/retrocss', '--pack-destination', tmp], {
    stdio: 'inherit',
    shell: process.platform === 'win32',
  });
  const tgz = fs.readdirSync(tmp).find((f) => f.endsWith('.tgz'));
  if (!tgz) die('npm pack produced no tarball');
  execFileSync('tar', ['-xzf', path.join(tmp, tgz), '-C', tmp]);
  return path.join(tmp, 'package');
}

const src = useNpm ? fromNpm() : from;
const pkgPath = path.join(src, 'package.json');
if (!fs.existsSync(pkgPath)) die(`no package.json at ${src} — pass --from <path to RetroCSS> or --npm`);
const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
if (pkg.name !== '@phantompixeldev/retrocss') die(`${src} is ${pkg.name}, not @phantompixeldev/retrocss`);

// A dist older than src means someone edited the SCSS and forgot to build. That
// bug is invisible once vendored, so it is caught here instead.
const scssDir = path.join(src, 'src', 'scss');
if (!useNpm && fs.existsSync(scssDir)) {
  const newest = (dir) =>
    fs.readdirSync(dir, { withFileTypes: true }).reduce((max, e) => {
      const p = path.join(dir, e.name);
      return Math.max(max, e.isDirectory() ? newest(p) : fs.statSync(p).mtimeMs);
    }, 0);
  const distStamp = fs.statSync(path.join(src, 'dist', 'retro.min.css')).mtimeMs;
  if (newest(scssDir) > distStamp) die('dist/retro.min.css is older than src/scss — run `npm run build` in RetroCSS first');
}

fs.mkdirSync(OUT, { recursive: true });
const meta = [];
for (const file of FILES) {
  const srcFile = path.join(src, 'dist', file);
  if (!fs.existsSync(srcFile)) die(`missing ${srcFile}`);
  // The sourcemap is not vendored — Hugo fingerprints the asset, so the
  // relative sourceMappingURL would resolve to nothing but a 404.
  const body = fs.readFileSync(srcFile, 'utf8').replace(/\/\*# sourceMappingURL=.*?\*\/\s*$/, '').replace(/\/\/# sourceMappingURL=.*$/m, '');
  fs.writeFileSync(path.join(OUT, file), body);
  const sha = createHash('sha384').update(body).digest('base64');
  meta.push({ file, bytes: Buffer.byteLength(body), integrity: `sha384-${sha}` });
  console.log(`vendored ${file} (${(Buffer.byteLength(body) / 1024).toFixed(1)} KB)`);
}

const toml = [
  '# Generated by scripts/vendor-retrocss.mjs — do not edit by hand.',
  `version = "${pkg.version}"`,
  `vendored = "${new Date().toISOString().slice(0, 10)}"`,
  'repository = "https://github.com/PhantomPixelDev/RetroCSS"',
  '',
  ...meta.flatMap((m) => [
    `[files."${m.file}"]`,
    `bytes = ${m.bytes}`,
    `integrity = "${m.integrity}"`,
    '',
  ]),
].join('\n');
fs.writeFileSync(path.join(THEME, 'data', 'retrocss.toml'), toml);
console.log(`pinned RetroCSS ${pkg.version} in data/retrocss.toml`);
